// src/pages/customer/BookingsPage.tsx
import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import BookingTile from "../../components/common/BookingTile";
import api from "../../utils/api";
import errorImage from "../../images/errorLoading.png";

const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 40px 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 60px;
`;

const Section = styled.div`
  width: 100%;
`;

const SectionTitle = styled.h2`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 800;
  color: #27374d;
  margin-bottom: 25px;
`;

const TilesContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 25px;
`;

const BookingsPage: React.FC = () => {
  const [upcoming, setUpcoming] = useState<any[]>([]);
  const [past, setPast] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadBookings = async () => {
      try {
        const res = await api.get("/bookings/me"); // ← NEW ENDPOINT
        const bookings = res.data || [];

        // classify bookings
        const now = new Date();

        const upcomingList: any[] = [];
        const pastList: any[] = [];

        bookings.forEach((b: any) => {
          const start = new Date(b.startTime);

          const status =
            start > now
              ? "upcoming"
              : b.status === "cancelled"
              ? "cancelled"
              : "past";

          const tileData = {
            id: b._id,
            date: start.toLocaleString("en-US"),
            image:
              b.business?.imageUrl
                ? `http://localhost:5000${b.business.imageUrl}`
                : errorImage,
            businessName: b.business?.businessName,
            location: `${b.business?.address}, ${b.business?.city}`,
            services: b.services.map((s: any) => s.name),
            status,
          };

          if (status === "upcoming") upcomingList.push(tileData);
          else pastList.push(tileData);
        });

        setUpcoming(upcomingList);
        setPast(pastList);
      } catch (err) {
        console.error("Error loading customer bookings:", err);
      } finally {
        setLoading(false);
      }
    };

    loadBookings();
  }, []);

  if (loading) {
    return (
      <PageWrapper>
        <TabBar type="customer" />
        <ContentWrapper>
          <SectionTitle>Loading your bookings…</SectionTitle>
        </ContentWrapper>
      </PageWrapper>
    );
  }

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        {/* UPCOMING SECTION */}
        <Section>
          <SectionTitle>Upcoming Bookings</SectionTitle>
          <TilesContainer>
            {upcoming.length === 0 && <p>No upcoming bookings.</p>}
            {upcoming.map((booking) => (
              <BookingTile
                key={booking.id}
                {...booking}
                onCancel={() => alert("Cancel booking: " + booking.id)}
                onViewReceipt={() => alert("Receipt for: " + booking.id)}
                onReschedule={() => alert("Reschedule: " + booking.id)}
              />
            ))}
          </TilesContainer>
        </Section>

        {/* PAST SECTION */}
        <Section>
          <SectionTitle>Past Bookings</SectionTitle>
          <TilesContainer>
            {past.length === 0 && <p>No past bookings.</p>}
            {past.map((booking) => (
              <BookingTile
                key={booking.id}
                {...booking}
                onLeaveRating={() => alert("Leave rating: " + booking.id)}
                onViewReceipt={() => alert("Receipt for: " + booking.id)}
              />
            ))}
          </TilesContainer>
        </Section>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default BookingsPage;
